/**
 * Change of one status: a member left out is unchanged; `null` for the whole status puts back
 * its default label and uses it again.
 * @nullable
 */
export type SpaceStatusPatch = {
  /**
     * New name, trimmed; a name made only of spaces is refused with `400 request.invalid`;
     * `null` puts back the default label.
     * @minLength 1
     * @maxLength 24
     * @nullable
     */
  name?: string | null;
  /** `true` to stop using the status; `todo` and `done` cannot be hidden. */
  hidden?: boolean;
} | null;

/**
 * Change of the statuses by key ("Statuts de « Produit »"); `null` puts back every default
 * ("Rétablir par défaut").
 * @nullable
 */
